function formatEventMeta(event) {
  const availability = event.seats > 0 ? `${event.seats} seats` : "Full";
  return `${event.category} · ${event.location} · ${availability}`;
}

function createEventCard(event) {
  const article = document.createElement("article");

  const heading = document.createElement("h2");
  heading.textContent = event.name;

  const meta = document.createElement("p");
  meta.textContent = formatEventMeta(event);

  article.append(heading);
  article.append(meta);
  return article;
}

const eventsElement = document.querySelector("#events");

function renderEvents(events) {
  eventsElement.textContent = "";

  for (const event of events) {
    eventsElement.append(createEventCard(event));
  }
}

let allEvents = [];

function filterEvents(category) {
  if (category === "all") return allEvents;
  return allEvents.filter((event) => event.category === category);
}

const filtersForm = document.querySelector("#filters");
const categorySelect = document.querySelector("#category");

filtersForm.addEventListener("submit", (event) => {
  event.preventDefault();

  const visibleEvents = filterEvents(categorySelect.value);
  renderEvents(visibleEvents);
});

async function fetchEvents() {
  const response = await fetch("./events.json");

  if (!response.ok) {
    throw new Error("Could not load events");
  }

  const records = await response.json();

  if (!Array.isArray(records)) {
    throw new Error("Events data must be an array.");
  }

  return records;
}

const statusElement = document.querySelector("#status");

function showStatus(message) {
  statusElement.textContent = message;
}

showStatus("Ready to load events.");

async function start() {
  showStatus("Loading events…");
  allEvents = await fetchEvents();

  if (allEvents.length === 0) {
    showStatus("No events found.");
    renderEvents([]);
    return;
  }

  showStatus(`${allEvents.length} events found.`);
  renderEvents(allEvents);
}

start();

